pub(crate) const CREATE: &str = "CREATE TABLE thesis_notes (\n    instrument TEXT PRIMARY KEY\n) STRICT;\nCREATE TABLE thesis_history (\n    instrument TEXT NOT NULL REFERENCES thesis_notes(instrument),\n    sequence INTEGER NOT NULL CHECK (sequence > 0),\n    payload TEXT NOT NULL,\n    PRIMARY KEY (instrument, sequence)\n) STRICT;\nCREATE TRIGGER thesis_history_no_update BEFORE UPDATE ON thesis_history BEGIN SELECT RAISE(ABORT, 'thesis history is append only'); END;\nCREATE TRIGGER thesis_history_no_delete BEFORE DELETE ON thesis_history BEGIN SELECT RAISE(ABORT, 'thesis history is append only'); END;\nCREATE TRIGGER thesis_history_no_replace BEFORE INSERT ON thesis_history WHEN EXISTS (SELECT 1 FROM thesis_history WHERE instrument = NEW.instrument AND sequence = NEW.sequence) BEGIN SELECT RAISE(ABORT, 'thesis history is append only'); END;\n";
pub(crate) const NOTE: &str = "SELECT instrument FROM thesis_notes WHERE instrument = ?1";
pub(crate) const INSERT_NOTE: &str = "INSERT INTO thesis_notes(instrument) VALUES (?1)";
pub(crate) const HISTORY: &str =
    "SELECT sequence, payload FROM thesis_history WHERE instrument = ?1 ORDER BY sequence";
pub(crate) const INSERT_HISTORY: &str =
    "INSERT INTO thesis_history(instrument, sequence, payload) VALUES (?1, ?2, ?3)";
pub(crate) const MIGRATE_0024: &str = "CREATE TABLE thesis_history_times (\n    instrument TEXT NOT NULL,\n    sequence INTEGER NOT NULL CHECK (sequence > 0),\n    seconds INTEGER NOT NULL,\n    nanos INTEGER NOT NULL CHECK (nanos >= 0 AND nanos < 1000000000),\n    offset INTEGER NOT NULL,\n    PRIMARY KEY (instrument, sequence),\n    FOREIGN KEY (instrument, sequence) REFERENCES thesis_history(instrument, sequence)\n) STRICT;\n";
pub(crate) const RECORD_TIME: &str = "INSERT OR IGNORE INTO thesis_history_times(instrument, sequence, seconds, nanos, offset) SELECT instrument, sequence, ?3, ?4, ?5 FROM thesis_history WHERE instrument = ?1 AND sequence = ?2";
pub(crate) const TIMES: &str = "SELECT sequence, seconds, nanos, offset FROM thesis_history_times WHERE instrument = ?1 ORDER BY sequence";
